#define _GNU_SOURCE
#include <signal.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <ucontext.h>
#include <unistd.h>

#define SLOTS (1u << 17)
static _Atomic uintptr_t pcs[SLOTS];
static _Atomic uint64_t counts[SLOTS];
static _Atomic uint64_t dropped;
static void sample(int sig, siginfo_t *info, void *context) {
    (void)sig; (void)info;
    uintptr_t pc = (uintptr_t)((ucontext_t *)context)->uc_mcontext.gregs[REG_RIP];
    unsigned slot = (unsigned)((pc >> 2) ^ (pc >> 19)) & (SLOTS - 1);
    for (unsigned n = 0; n < SLOTS; n++, slot = (slot + 1) & (SLOTS - 1)) {
        uintptr_t expected = 0;
        if (atomic_compare_exchange_strong_explicit(&pcs[slot], &expected, pc,
                memory_order_relaxed, memory_order_relaxed) || expected == pc) {
            atomic_fetch_add_explicit(&counts[slot], 1, memory_order_relaxed);
            return;
        }
    }
    atomic_fetch_add_explicit(&dropped, 1, memory_order_relaxed);
}
__attribute__((constructor)) static void start(void) {
    if (!getenv("CAD_NATIVE_PROFILE")) return;
    struct sigaction action = {0};
    action.sa_sigaction = sample;
    action.sa_flags = SA_SIGINFO | SA_RESTART;
    sigemptyset(&action.sa_mask);
    if (sigaction(SIGPROF, &action, NULL)) _exit(125);
    struct itimerval timer = {{0, 1000}, {0, 1000}};
    if (setitimer(ITIMER_PROF, &timer, NULL)) _exit(125);
}
__attribute__((destructor)) static void finish(void) {
    const char *path = getenv("CAD_NATIVE_PROFILE");
    if (!path) return;
    struct itimerval timer = {0};
    setitimer(ITIMER_PROF, &timer, NULL);
    FILE *out = fopen(path, "w");
    if (!out) return;
    fprintf(out, "dropped %llu\n", (unsigned long long)dropped);
    for (unsigned i = 0; i < SLOTS; i++)
        if (pcs[i]) fprintf(out, "%lx %llu\n", (unsigned long)pcs[i],
                            (unsigned long long)counts[i]);
    fprintf(out, "maps\n");
    FILE *maps = fopen("/proc/self/maps", "r");
    if (maps) {
        char line[4096];
        while (fgets(line, sizeof(line), maps))
            if (strstr(line, "r-xp")) fputs(line, out);
        fclose(maps);
    }
    fclose(out);
}
